H.background();
H.text("Dalton's law:  P_i = X_i * P_total", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Each gas contributes pressure in proportion to its mole fraction", 24, 52, { color: H.colors.sub, size: 13 });
const Ptot = Math.max(0.2, P.Ptot);
let a = Math.max(0, P.nA);
let b = Math.max(0, P.nB);
let c = 1;
let sum = a + b + c;
if (sum <= 0) { a = 1; b = 1; c = 1; sum = 3; }
const gases = [
  { name: "N2", n: a, col: H.colors.accent },
  { name: "O2", n: b, col: H.colors.good },
  { name: "Ar", n: c, col: H.colors.violet }
];
const bx = 60, by = 100, bw = 360, bh = 330;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 3, radius: 8 });
H.text("gas mixture", bx + 8, by + 16, { color: H.colors.sub, size: 11 });
let total = 0;
for (const g of gases) total += g.n;
let drawn = 0;
for (let gi = 0; gi < gases.length; gi++) {
  const g = gases[gi];
  const count = Math.max(1, Math.round((g.n / total) * 36));
  for (let i = 0; i < count; i++) {
    const ph = (drawn + i) * 1.3 + gi;
    const ax = (bw - 36) / 2, ay = (bh - 36) / 2;
    const x = bx + 18 + ax + ax * Math.sin(t * 1.1 + ph);
    const y = by + 18 + ay + ay * Math.cos(t * 1.27 + ph * 1.1);
    H.circle(x, y, 5, { fill: g.col });
  }
  drawn += count;
}
const sx = 500, sy = 120, sw = 90, sh = 300;
H.line(sx - 10, sy + sh, sx + sw + 60, sy + sh, { color: H.colors.grid, width: 2 });
H.text("partial P (atm)", sx, sy - 14, { color: H.colors.sub, size: 12 });
let yCursor = sy + sh;
for (let gi = 0; gi < gases.length; gi++) {
  const g = gases[gi];
  const X = g.n / total;
  const Pi = X * Ptot;
  const segH = (Pi / Math.max(0.001, Ptot)) * sh;
  const top = yCursor - segH;
  H.rect(sx, top, sw, segH, { fill: g.col, stroke: H.colors.ink, width: 1 });
  H.text(g.name + ": " + Pi.toFixed(2), sx + sw + 8, (top + yCursor) / 2, { color: g.col, size: 12, baseline: "middle" });
  H.text("X=" + X.toFixed(2), sx + sw / 2, top + segH / 2, { color: H.colors.bg, size: 11, align: "center", baseline: "middle", weight: 700 });
  yCursor = top;
}
H.text("P_total = " + Ptot.toFixed(2) + " atm", 24, 500, { color: H.colors.ink, size: 15, weight: 700 });
H.text("sum of X = 1.00  ->  sum of P_i = P_total  (Dalton)", 24, 526, { color: H.colors.sub, size: 13 });
